      heroLede: "<strong>b012_data</strong> convierte una clase Dart simple en una entidad persistente. Las sentencias CRUD, las transacciones, las proyecciones y la E/S de archivos siguen seis convenciones simples. Sin SQL escrito a mano. Sin código repetitivo de repositorios. Solo Dart.",
