      heroMeta2: "6 plataformas, una API",
      heroMeta3: "Cifrado opcional",
      panelAria: "Entidad de ejemplo",
      panelQuote: "«Seis miembros bien conocidos y tu clase es persistente».",
      overviewKicker: "&sect; 00 &middot; Resumen",
      overviewTitle: "Cuatro ideas. Un paquete.",
      overviewSub: "b012_data mantiene la superficie pequeña a propósito: una clase es el esquema, una instancia es una fila y dos singletons hacen el resto &mdash; <code>DataAccess</code> para la base de datos, <code>DiscData</code> para los archivos.",
      feature1Title: "Entidades estilo Spring",
      feature1Body: "Declara clave primaria, columnas no nulas, columnas únicas, restricciones CHECK, valores por defecto y claves foráneas como getters simples. <code>DataAccess</code> los convierte en SQL.",
      feature2Title: "Todo el CRUD, gratis",
      feature2Body: "Inserta, inserta en lote, lee por predicado, proyecta columnas, actualiza, elimina y cuenta con APIs genéricas tipadas.",
      feature3Title: "Funciona donde funcione Flutter",
      feature3Body: "Las mismas llamadas en Android, iOS, macOS, Linux, Windows y en el navegador: b012_data elige el motor SQLite de cada <a href=\"#platforms\">plataforma</a>.",
      feature4Title: "Bytes en disco, metadatos en SQLite",
      feature4Body: "<code>DiscData</code> lee, escribe, añade y resuelve archivos binarios como texto, Base64, <code>Uint8List</code> o <code>Image</code> de Flutter.",
      newKicker: "&sect; 2.1 &middot; Novedades",
      newTitle: "Más robusto, sin cambiar la forma de usarlo.",
      newSub: "Todos los métodos de la 2.0.3 conservan su nombre, sus parámetros y su comportamiento por defecto &mdash; incluido devolver <code>false</code>, <code>null</code> o <code>[]</code> cuando fallan. Todo lo nuevo es opcional y se activa explícitamente: cada tarjeta abre su parte de la guía.",
      new1Title: "<a href=\"#v21-security\">Valores enlazados</a>",
      new1Body: "Marcadores <code>?</code> y <code>whereArgs</code> en todos los métodos que filtran.",
      new2Title: "<a href=\"#v21-errors\">Modo estricto</a>",
      new2Body: "El error real, lanzado o pasado a <code>onError</code>, en lugar de <code>false</code> o <code>[]</code>.",
      new3Title: "<a href=\"#v21-transactions\">Transacciones</a>",
      new3Body: "Todo o nada, a lo largo de varias llamadas.",
      new4Title: "<a href=\"#v21-queries\">Consultas</a>",
      new4Body: "Paginación, ordenación y SQL directo, con valores enlazados.",
      new5Title: "<a href=\"#v21-keys\">Claves e índices</a>",
      new5Body: "Claves primarias compuestas, índices, <code>INSERT OR REPLACE</code>, verificación de claves foráneas.",
      new6Title: "<a href=\"#v21-names\">Evolución del esquema</a>",
      new6Body: "Nombres de tabla estables, columnas nuevas añadidas, migraciones versionadas.",
      new7Title: "<a href=\"#v21-location\">Ubicación de los datos y archivos</a>",
      new7Body: "Una carpeta de datos por aplicación en Windows y Linux; archivos escritos de una sola vez.",
      new8Title: "<a href=\"#v21-web\">Web</a>",
      new8Body: "La misma API en un navegador, sobre SQLite compilado a WebAssembly.",
      new9Title: "<a href=\"#v21-encryption\">Cifrado</a>",
      new9Body: "Base de datos y archivos cifrados, nunca abiertos sin la clave.",
      newFoot: "¿Vas a actualizar? Consulta los <a href=\"#install-req\">requisitos</a> y luego el <a class=\"ext-link\" href=\"https://pub.dev/packages/b012_data/changelog\" target=\"_blank\" rel=\"noopener\">registro de cambios</a> completo.",
