      installRun: "<em>Depois execute:</em>",
      installReq: "A 2.1 exige Dart 3.12 e Flutter 3.44 ou mais recentes (como os pacotes <code>sqflite</code> atuais); um aplicativo em um Flutter mais antigo continua resolvendo a 2.0.3.",
      installImport: "Importe a biblioteca de que você precisa: <code>b012_sqlflite_easy.dart</code> para o banco de dados, <code>b012_disc_data.dart</code> para os arquivos.",
      installBindings: "Antes de chamar qualquer método que precise do diretório de documentos (<code>databasesPath</code>, <code>filesPath</code>, &hellip;), garanta que os bindings do Flutter estejam inicializados:",
