      reachKicker: "&sect; 08 &middot; Alcance",
      reachTitle: "Um import. Seis destinos.",
      reachSub: "O mesmo código onde o Flutter roda &mdash; SQLite nativo no mobile, FFI no desktop, WebAssembly no navegador.",
      reachTested: "A 2.1 foi testada no Windows (testes unitários, SQLite3MultipleCiphers real), no Chrome (o aplicativo de verificação em <code>tool/web_check</code>) e em um emulador Android. iOS, macOS e Linux compartilham os mesmos caminhos de código.",
      ctaKicker: "&sect; 09 &middot; Mãos à obra",
