      heroTitleMain: "Objekt-relationale&nbsp;Abbildung,",
      heroTitleTail: "der Spring-Boot-Weg für Dart / Flutter.",
      heroLede: "<strong>b012_data</strong> macht aus einer einfachen Dart-Klasse eine persistente Entität. CRUD, Transaktionen, Projektionen und Datei-I/O folgen sechs einfachen Konventionen. Ohne handgeschriebenes SQL. Ohne Repository-Boilerplate. Nur Dart.",
      installLabel: "zu <code>pubspec.yaml</code> hinzufügen",
      heroReadGuide: "Leitfaden lesen &rarr;",
      heroDeclareEntity: "Entität deklarieren",
      heroMetaAria: "Wichtigste Merkmale des Pakets",
      heroMeta1: "Kein SQL zu pflegen",
      heroMeta2: "6 Plattformen, eine API",
      heroMeta3: "Optionale Verschlüsselung",
      panelAria: "Beispielentität",
      panelQuote: "„Sechs bekannte Mitglieder, und Ihre Klasse ist persistent.“",
      overviewKicker: "&sect; 00 &middot; Überblick",
      overviewTitle: "Vier Ideen. Ein Paket.",
      overviewSub: "b012_data hält die Oberfläche bewusst klein: eine Klasse ist das Schema, eine Instanz ist eine Zeile, und zwei Singletons erledigen den Rest &mdash; <code>DataAccess</code> für die Datenbank, <code>DiscData</code> für Dateien.",
      feature1Title: "Entitäten im Spring-Stil",
      feature1Body: "Primärschlüssel, Non-Null, Uniques, Checks, Defaults und Fremdschlüssel werden als einfache Getter deklariert. <code>DataAccess</code> erzeugt daraus SQL.",
      feature2Title: "Vollständiges CRUD gratis",
      feature2Body: "Einfügen, Masseneinfügen, Lesen per Prädikat, Projektionen, Aktualisieren, Löschen und Zählen mit typisierten generischen APIs.",
      feature3Title: "Läuft überall, wo Flutter läuft",
      feature3Body: "Dieselben Aufrufe auf Android, iOS, macOS, Linux, Windows und im Browser: b012_data wählt für jede <a href=\"#platforms\">Plattform</a> die passende SQLite-Engine.",
      feature4Title: "Bytes auf der Platte, Metadaten in SQLite",
      feature4Body: "<code>DiscData</code> liest, schreibt, ergänzt und löst Binärdateien als Text, Base64, <code>Uint8List</code> oder Flutter-<code>Image</code> auf.",
      newKicker: "&sect; 2.1 &middot; Neuerungen",
      newTitle: "Robuster, ohne dass sich die Verwendung ändert.",
      newSub: "Jede Methode aus 2.0.3 behält ihren Namen, ihre Parameter und ihr Standardverhalten &mdash; einschließlich der Rückgabe von <code>false</code>, <code>null</code> oder <code>[]</code> bei einem Fehler. Alles Neue ist optional: Jede Karte öffnet ihren Teil des Leitfadens.",
      new1Title: "<a href=\"#v21-security\">Gebundene Werte</a>",
      new1Body: "<code>?</code>-Platzhalter und <code>whereArgs</code> bei jeder Methode, die filtert.",
      new2Title: "<a href=\"#v21-errors\">Strikter Modus</a>",
      new2Body: "Der echte Fehler, geworfen oder an <code>onError</code> übergeben, statt <code>false</code> oder <code>[]</code>.",
      new3Title: "<a href=\"#v21-transactions\">Transaktionen</a>",
      new3Body: "Alles oder nichts, über mehrere Aufrufe hinweg.",
      new4Title: "<a href=\"#v21-queries\">Abfragen</a>",
      new4Body: "Paginierung, Sortierung und rohes SQL, mit gebundenen Werten.",
      new5Title: "<a href=\"#v21-keys\">Schlüssel und Indizes</a>",
      new5Body: "Zusammengesetzte Primärschlüssel, Indizes, <code>INSERT OR REPLACE</code>, erzwungene Fremdschlüssel.",
      new6Title: "<a href=\"#v21-names\">Schemaentwicklung</a>",
      new6Body: "Stabile Tabellennamen, neu hinzugefügte Spalten, versionierte Migrationen.",
      new7Title: "<a href=\"#v21-location\">Datenspeicherort &amp; Dateien</a>",
      new7Body: "Ein Datenordner pro Anwendung unter Windows und Linux; Dateien werden in einem Zug geschrieben.",
      new8Title: "<a href=\"#v21-web\">Web</a>",
      new8Body: "Dieselbe API im Browser, auf Basis von SQLite, nach WebAssembly kompiliert.",
      new9Title: "<a href=\"#v21-encryption\">Verschlüsselung</a>",
      new9Body: "Verschlüsselte Datenbank und Dateien, die nie ohne den Schlüssel geöffnet werden.",
      newFoot: "Sie aktualisieren? Prüfen Sie die <a href=\"#install-req\">Voraussetzungen</a> und dann das vollständige <a class=\"ext-link\" href=\"https://pub.dev/packages/b012_data/changelog\" target=\"_blank\" rel=\"noopener\">Änderungsprotokoll</a>.",
