      crudCreateBody: "<code>insertObjet</code> вставляет одну сущность, <code>insertObjetList</code> — список; оба возвращают <code>bool</code>. Если вставка одной из строк списка не удалась, предыдущие строки сохраняются: чтобы получить «всё или ничего», вызывайте его внутри <a href=\"#v21-transactions\">транзакции</a>. <code>newKey</code> возвращает случайный ключ из 32 символов.",
      crudReadTitle: "Одна строка, много строк, один столбец или несколько столбцов.",
      crudReadBody: "Условие передаётся в <code>afterWhere</code> с <code>?</code> на месте каждого значения, а сами значения — в <code>whereArgs</code>: значение никогда не вставляется в текст SQL. Булевы значения и даты преобразуются так, как их хранит b012_data.",
