      discTitle: "Файлы на диске",
      discSub: "Singleton <code>DiscData</code> читает, пишет, дописывает и проверяет файлы. Он возвращает текст, Base64, <code>Uint8List</code> или Flutter-виджет <code>Image</code>.",
      discIntro: "Храните метаданные в SQLite, бинарные данные на диске и связывайте одно с другим одним вызовом.",
