      overviewKicker: "&sect; 00 &middot; 概览",
      overviewTitle: "四个理念，一个包。",
      overviewSub: "b012_data 故意保持接口简洁：类就是表结构，实例就是一行数据，其余工作由两个单例完成 &mdash; <code>DataAccess</code> 负责数据库，<code>DiscData</code> 负责文件。",
      feature1Title: "Spring 风格实体",
      feature1Body: "将主键、非空列、唯一约束、检查、默认值和外键声明为普通 Getter。<code>DataAccess</code> 会将它们转换为 SQL。",
      feature2Title: "免费获得完整 CRUD",
      feature2Body: "通过类型安全的泛型 API 进行插入、批量插入、按谓词读取、列投影、更新、删除和计数。",
      feature3Title: "Flutter 能运行的地方，它就能运行",
      feature3Body: "在 Android、iOS、macOS、Linux、Windows 和浏览器中调用方式完全相同：b012_data 会为每个<a href=\"#platforms\">平台</a>选择合适的 SQLite 引擎。",
      feature4Title: "磁盘存字节，SQLite 存元数据",
      feature4Body: "<code>DiscData</code> 以文本、Base64、<code>Uint8List</code> 或 Flutter <code>Image</code> 形式读取、写入、追加和解析二进制文件。",
      newKicker: "&sect; 2.1 &middot; 新功能",
      newTitle: "更加稳健，用法不变。",
      newSub: "2.0.3 的每个方法都保留了原有的名称、参数和默认行为 &mdash; 包括失败时返回 <code>false</code>、<code>null</code> 或 <code>[]</code>。所有新功能都需主动启用：每张卡片都会打开指南中对应的部分。",
      new1Title: "<a href=\"#v21-security\">绑定值</a>",
