      installBindings: "在调用任何需要文档目录的方法（<code>databasesPath</code>、<code>filesPath</code> 等）之前，请确保 Flutter 绑定已初始化：",
      installNoteLabel: "注意 &mdash; 默认数据库",
      installNoteBody: "首次访问时会在应用的数据库文件夹中创建名为 <code>sqlf_easy.db</code> 的默认数据库（参见<a href=\"#v21-location\">数据存放位置</a>）。如需其他数据库，请使用 <code>changeDB</code>。",
      entityKicker: "&sect; 02 &middot; 约定",
      entityTitle: "声明实体",
