      reachSub: "Flutter 运行之处皆是同一份代码 &mdash; 移动端原生 SQLite，桌面端 FFI，浏览器中 WebAssembly。",
      reachTested: "2.1 已在 Windows（单元测试，真实的 SQLite3MultipleCiphers）、Chrome（<code>tool/web_check</code> 中的检查应用）和 Android 模拟器上测试。iOS、macOS 和 Linux 共用相同的代码路径。",
