      note2Title: "Dart Map vs. SQLite 就緒 Map",
      note2Body: "<code>insertObjet</code> 和 <code>insertObjetList</code> 內部使用 <code>mapToUse(entity.toMap())</code> 轉換您的實體 Map。當您需要純 Dart Map 時，請自行呼叫 <code>mapToUse(entity.toMap(), forDB: false)</code>。",
      exampleKicker: "&sect; 07 &middot; 沙盒",
