      overviewKicker: "&sect; 00 &middot; 概要",
      overviewTitle: "4つの理念。1つのパッケージ。",
      overviewSub: "b012_data は意図的にインターフェースを小さく保っています。クラスはスキーマ、インスタンスは行であり、残りは2つのシングルトンが担います &mdash; データベースには <code>DataAccess</code>、ファイルには <code>DiscData</code>。",
      feature1Title: "Springスタイルのエンティティ",
      feature1Body: "主キー、非nullカラム、ユニーク制約、チェック、デフォルト値、外部キーを普通のgetterとして宣言します。<code>DataAccess</code>がそれらをSQLに変換します。",
      feature2Title: "完全なCRUDを無料で",
      feature2Body: "型安全なジェネリックAPIを使用して、挿入、一括挿入、述語による読み取り、カラムプロジェクション、更新、削除、カウントを行えます。",
      feature3Title: "Flutter が動く場所ならどこでも動作",
      feature3Body: "Android、iOS、macOS、Linux、Windows、そしてブラウザでも同じ呼び出しが使えます。b012_data が<a href=\"#platforms\">プラットフォーム</a>ごとに SQLite エンジンを選びます。",
      feature4Title: "ディスクにバイト、SQLiteにメタデータ",
      feature4Body: "<code>DiscData</code>は、バイナリファイルをテキスト、Base64、<code>Uint8List</code>、またはFlutterの<code>Image</code>として読み込み、書き込み、追記、解決します。",
      newKicker: "&sect; 2.1 &middot; 新機能",
      newTitle: "使い方はそのままに、より堅牢に。",
      newSub: "2.0.3 のすべてのメソッドは、名前、パラメータ、デフォルトの動作をそのまま維持しています &mdash; 失敗時に <code>false</code>、<code>null</code>、<code>[]</code> を返す動作も含めてです。新機能はすべてオプトインです。各カードからガイドの該当部分を開けます。",
      new1Title: "<a href=\"#v21-security\">バインド値</a>",
      new1Body: "絞り込みを行うすべてのメソッドで <code>?</code> プレースホルダーと <code>whereArgs</code> を利用できます。",
      new2Title: "<a href=\"#v21-errors\">厳格モード</a>",
      new2Body: "<code>false</code> や <code>[]</code> の代わりに、実際のエラーをスローするか <code>onError</code> に渡します。",
      new3Title: "<a href=\"#v21-transactions\">トランザクション</a>",
      new3Body: "複数の呼び出しをまたいで、全か無か。",
      new4Title: "<a href=\"#v21-queries\">クエリ</a>",
      new4Body: "ページング、ソート、生の SQL。いずれもバインド値に対応。",
      new5Title: "<a href=\"#v21-keys\">キーとインデックス</a>",
      new5Body: "複合主キー、インデックス、<code>INSERT OR REPLACE</code>、外部キーの強制。",
      new6Title: "<a href=\"#v21-names\">スキーマの進化</a>",
      new6Body: "安定したテーブル名、新しいカラムの追加、バージョン管理されたマイグレーション。",
      new7Title: "<a href=\"#v21-location\">データの保存場所とファイル</a>",
      new7Body: "Windows と Linux ではアプリごとに1つのデータフォルダ。ファイルは一度にまとめて書き込まれます。",
      new8Title: "<a href=\"#v21-web\">Web</a>",
      new8Body: "ブラウザでも同じ API。WebAssembly にコンパイルされた SQLite 上で動作します。",
      new9Title: "<a href=\"#v21-encryption\">暗号化</a>",
      new9Body: "暗号化されたデータベースとファイル。鍵なしで開かれることはありません。",
      newFoot: "アップグレードしますか？まず<a href=\"#install-req\">動作要件</a>を確認し、次に完全な<a class=\"ext-link\" href=\"https://pub.dev/packages/b012_data/changelog\" target=\"_blank\" rel=\"noopener\">変更履歴</a>をご覧ください。",
      tocAria: "目次",
      tocLabel: "目次",
