      step2Heading: "कंस्ट्रेंट्स <span class=\"steps__flag steps__flag--soft\">वैकल्पिक</span>",
      step2Body: "Non-null कॉलम, यूनिक, चेक, डिफॉल्ट और फॉरेन की, हर एक को गेटर के रूप में व्यक्त किया जाता है।",
      step3Heading: "बिना नाम वाला कंस्ट्रक्टर <span class=\"steps__flag\">ज़रूरी</span>",
      step3Body: "नीचे दिए गए <code>fromMap</code> कॉलबैक से एंटिटी को इंस्टेंटियेट करने के लिए पैकेज द्वारा इस्तेमाल किया जाता है।",
      step4Heading: "सीरियलाइज़ेशन <code>toMap</code> <span class=\"steps__flag\">ज़रूरी</span>",
      step4Body: "जब कोई फ़ील्ड <code>null</code> हो, तब भी उसका <code>ColumnType</code> पैकेज को कॉलम का टाइप बताता है। <code>notNulls</code> वाले फ़ील्ड के लिए इसे छोड़ा जा सकता है, क्योंकि इंसर्ट के समय वे कभी नल नहीं होते।",
      step5Heading: "नेम्ड <code>fromMap</code> कंस्ट्रक्टर <span class=\"steps__flag\">ज़रूरी</span>",
