      note1Body: "معظم الدوال الخاصة بالكيانات ترمي <code>DatabaseException('no such table: ...')</code> عندما لا يكون الجدول موجودًا. أما <code>updateWholeObject</code> و<code>updateSomeColumnsOf</code> و<code>getAColumnFromWithTableName</code> و<code>getAColumnFrom</code> فتكتفي بتسجيل الخطأ عبر <code>debugPrint</code> و<code>onError</code> &mdash; ما لم يُفعَّل <code>strict</code>.",
      note2Title: "خريطة Dart مقابل خريطة جاهزة لـ SQLite",
