      heroLede: "<strong>b012_data</strong> mengubah kelas Dart biasa menjadi entitas persisten. CRUD, transaksi, proyeksi, dan I/O berkas mengikuti enam konvensi sederhana. Tanpa SQL manual. Tanpa boilerplate repository. Hanya Dart.",
