      panelAria: "Contoh entitas",
      panelQuote: "“Enam anggota yang sudah dikenal, dan kelas Anda menjadi persisten.”",
      overviewKicker: "&sect; 00 &middot; Ringkasan",
      overviewTitle: "Empat ide. Satu paket.",
      overviewSub: "b012_data sengaja menjaga permukaan API tetap sempit: kelas adalah skema, instance adalah baris, dan dua singleton menangani sisanya &mdash; <code>DataAccess</code> untuk basis data, <code>DiscData</code> untuk berkas.",
      feature1Title: "Entitas gaya Spring",
      feature1Body: "Deklarasikan primary key, kolom non-null, unik, check, default, dan foreign key sebagai getter biasa. <code>DataAccess</code> mengubahnya menjadi SQL.",
      feature2Title: "Setiap CRUD, gratis",
      feature2Body: "Insert, bulk-insert, baca berdasarkan predikat, proyeksi kolom, update, delete, dan count dengan API generik yang tipenya aman.",
      feature3Title: "Berjalan di mana pun Flutter berjalan",
      feature3Body: "Panggilan yang sama di Android, iOS, macOS, Linux, Windows, dan di browser: b012_data memilih mesin SQLite untuk setiap <a href=\"#platforms\">platform</a>.",
      feature4Title: "Byte di disk, metadata di SQLite",
      feature4Body: "<code>DiscData</code> membaca, menulis, menambah, dan mengolah file biner sebagai teks, Base64, <code>Uint8List</code> atau Flutter <code>Image</code>.",
      newKicker: "&sect; 2.1 &middot; Yang baru",
      newTitle: "Lebih tangguh, tanpa mengubah cara Anda memakainya.",
      newSub: "Setiap metode 2.0.3 mempertahankan nama, parameter, dan perilaku bawaannya &mdash; termasuk mengembalikan <code>false</code>, <code>null</code>, atau <code>[]</code> saat gagal. Semua yang baru harus diaktifkan sendiri: setiap kartu membuka bagian panduannya.",
