      newSub: "Mọi phương thức của 2.0.3 vẫn giữ nguyên tên, tham số và hành vi mặc định &mdash; kể cả việc trả về <code>false</code>, <code>null</code> hoặc <code>[]</code> khi thất bại. Mọi tính năng mới chỉ có hiệu lực khi bạn chủ động bật: mỗi thẻ mở phần tương ứng của hướng dẫn.",
      new1Title: "<a href=\"#v21-security\">Giá trị ràng buộc</a>",
      new1Body: "Placeholder <code>?</code> và <code>whereArgs</code> ở mọi phương thức có lọc dữ liệu.",
      new2Title: "<a href=\"#v21-errors\">Chế độ nghiêm ngặt</a>",
