      new5Title: "<a href=\"#v21-keys\">Khóa và chỉ mục</a>",
      new5Body: "Khóa chính phức hợp, chỉ mục, <code>INSERT OR REPLACE</code>, khóa ngoại được thực thi.",
      new6Title: "<a href=\"#v21-names\">Tiến hóa schema</a>",
      new6Body: "Tên bảng ổn định, tự thêm cột mới, di chuyển dữ liệu theo phiên bản.",
