      new9Body: "Cơ sở dữ liệu và tệp được mã hóa, không bao giờ mở được nếu thiếu khóa.",
      newFoot: "Bạn đang nâng cấp? Hãy kiểm tra các <a href=\"#install-req\">yêu cầu</a>, sau đó xem toàn bộ <a class=\"ext-link\" href=\"https://pub.dev/packages/b012_data/changelog\" target=\"_blank\" rel=\"noopener\">nhật ký thay đổi</a>.",
