      installRun: "<em>Quindi esegui:</em>",
      installReq: "La 2.1 richiede Dart 3.12 e Flutter 3.44 o successivi (come gli attuali pacchetti <code>sqflite</code>); un'applicazione con un Flutter più vecchio continua a risolvere la 2.0.3.",
      installImport: "Importa la libreria che ti serve: <code>b012_sqlflite_easy.dart</code> per il database, <code>b012_disc_data.dart</code> per i file.",
