      installNoteLabel: "Nota &mdash; database predefinito",
      installNoteBody: "Il primo accesso crea un database predefinito chiamato <code>sqlf_easy.db</code> nella cartella dei database dell'applicazione (vedi <a href=\"#v21-location\">dove vivono i tuoi dati</a>). Usa <code>changeDB</code> se ne vuoi un altro.",
