      step4Heading: "Serializzazione <code>toMap</code> <span class=\"steps__flag\">richiesto</span>",
      step4Body: "Quando un campo è <code>null</code>, il suo <code>ColumnType</code> indica comunque al pacchetto il tipo della colonna. Può essere omesso per i campi di <code>notNulls</code>, che non sono mai null al momento dell'inserimento.",
      step5Heading: "Costruttore nominato <code>fromMap</code> <span class=\"steps__flag\">richiesto</span>",
      step5Body: "Deserializzazione da una singola riga SQLite. SQLite non ha un tipo booleano né un tipo data: le funzioni di supporto <code>boolean</code> e <code>dateTime</code> riconvertono questi valori.",
      step6Heading: "<code>fromMap</code> lato istanza <span class=\"steps__flag\">richiesto</span>",
      step6Body: "Avvolge il costruttore nominato in modo che i getter generici possano chiamarlo da qualsiasi istanza.",
      crudKicker: "&sect; 03 &middot; Runtime",
      crudTitle: "Percorso CRUD",
      crudSub: "Ogni chiamata qui sotto è l'equivalente di alto livello di un metodo di repository Spring Data JPA, guidato solo attraverso <code>DataAccess.instance</code>: al massimo, scrivi una condizione <code>WHERE</code>.",
      crudIntro: "Inizia ispezionando lo schema generato dalla tua entità, quindi verifica se la tabella esiste già:",
      crudCreateTitle: "Una riga o un'intera lista.",
      crudCreateBody: "<code>insertObjet</code> inserisce un'entità, <code>insertObjetList</code> una lista; entrambi restituiscono un <code>bool</code>. Se una riga della lista fallisce, le righe precedenti vengono mantenute: esegui la chiamata in una <a href=\"#v21-transactions\">transazione</a> per avere tutto o niente. <code>newKey</code> restituisce una chiave casuale di 32 caratteri.",
      crudReadTitle: "Una riga, molte righe, una colonna singola o più colonne.",
      crudReadBody: "La condizione va in <code>afterWhere</code>, con un <code>?</code> per ogni valore, e i valori vanno in <code>whereArgs</code>: un valore non viene mai incollato nel codice SQL. Booleani e date vengono convertiti nel modo in cui b012_data li memorizza.",
      crudProjection: "Proiezione &mdash; colonna singola o un insieme di colonne:",
      crudUpdateTitle: "I valori seguono l'ordine <code>columnsToUpdate</code> + <code>whereColumns</code>.",
      crudUpdateBody: "Qui: imposta <code>firstName = 'developer'</code> e <code>lastName = '2022'</code> dove <code>firstName = 'Birane' AND lastName = 'KEBE'</code>.",
      crudUpdateMcop: "Le <code>whereColumns</code> sono combinate con <code>AND</code>; passa <code>whereMcop: 'OR'</code> per combinarle con <code>OR</code>.",
