      reachTested: "La 2.1 è stata testata su Windows (test unitari, vero SQLite3MultipleCiphers), in Chrome (l'applicazione di verifica in <code>tool/web_check</code>) e su un emulatore Android. iOS, macOS e Linux condividono gli stessi percorsi di codice.",
      ctaKicker: "&sect; 09 &middot; Pubblica",
