      crudTitle: "CRUD-rondleiding",
      crudSub: "Elke aanroep hieronder is het equivalent op hoog niveau van een Spring Data JPA-repositorymethode, uitsluitend aangestuurd via <code>DataAccess.instance</code>: hooguit schrijf je een <code>WHERE</code>-voorwaarde.",
      crudIntro: "Begin met het inspecteren van het schema dat voor je entiteit is gegenereerd en controleer vervolgens of de tabel al bestaat:",
      crudCreateTitle: "Eén rij, of een hele lijst.",
      crudCreateBody: "<code>insertObjet</code> voegt één entiteit in, <code>insertObjetList</code> een lijst; beide geven een <code>bool</code> terug. Als een rij van de lijst mislukt, blijven de rijen ervoor behouden: roep de methode aan binnen een <a href=\"#v21-transactions\">transactie</a> voor alles of niets. <code>newKey</code> geeft een willekeurige sleutel van 32 tekens terug.",
      crudReadTitle: "Eén rij, veel rijen, één kolom of meerdere kolommen.",
      crudReadBody: "De voorwaarde komt in <code>afterWhere</code>, met een <code>?</code> voor elke waarde, en de waarden komen in <code>whereArgs</code>: een waarde wordt nooit in de SQL geplakt. Booleans en datums worden omgezet zoals b012_data ze opslaat.",
