      note1Title: "Wyjątki brakującej tabeli",
      note1Body: "Większość metod encji rzuca <code>DatabaseException('no such table: ...')</code>, gdy tabela nie istnieje. <code>updateWholeObject</code>, <code>updateSomeColumnsOf</code>, <code>getAColumnFromWithTableName</code> i <code>getAColumnFrom</code> tylko zapisują błąd przez <code>debugPrint</code> i <code>onError</code> &mdash; chyba że ustawiono <code>strict</code>.",
      note2Title: "Dart map vs map gotowa na SQLite",
      note2Body: "<code>insertObjet</code> i <code>insertObjetList</code> konwertują mapę encji za pomocą <code>mapToUse(entity.toMap())</code>. Wywołaj <code>mapToUse(entity.toMap(), forDB: false)</code> na potrzeby zwykłej mapy Dart.",
