      installReq: "2.1-এর জন্য Dart 3.12 ও Flutter 3.44 বা তার নতুন সংস্করণ লাগে (বর্তমান <code>sqflite</code> প্যাকেজগুলোরও তাই লাগে); পুরোনো Flutter-এর অ্যাপ 2.0.3-ই পেতে থাকবে।",
