      installNoteLabel: "দ্রষ্টব্য &mdash; ডিফল্ট ডাটাবেস",
      installNoteBody: "প্রথমবার অ্যাক্সেস করলে অ্যাপের databases ফোল্ডারে <code>sqlf_easy.db</code> নামে একটি ডিফল্ট ডেটাবেস তৈরি হয় (দেখুন <a href=\"#v21-location\">আপনার ডেটা কোথায় থাকে</a>)। অন্য ডেটাবেস চাইলে <code>changeDB</code> ব্যবহার করুন।",
      entityKicker: "&sect; ০২ &middot; কনভেনশন",
      entityTitle: "এনটিটি ঘোষণা",
      entitySub: "এনটিটি হলো একটি সাধারণ Dart ক্লাস যা ছয়টি পরিচিত মেম্বার প্রকাশ করে। <code>DataAccess</code> এগুলো একবার পড়ে এবং প্রয়োজনীয় প্রতিটি স্টেটমেন্ট তৈরি করে।",
      step1Heading: "প্রাইমারি কি <span class=\"steps__flag\">প্রয়োজনীয়</span>",
      step1Body: "একটি <code>MapEntry</code> যার কি হলো কলামের নাম এবং ভ্যালু হলো <code>AUTOINCREMENT</code> ব্যবহারের জন্য <code>true</code>। একাধিক কলাম দিয়ে গঠিত প্রাইমারি কি-এর জন্য এর বদলে <a href=\"#v21-keys\"><code>pKeys</code></a> ঘোষণা করুন।",
      step2Heading: "কনস্ট্রেইন্ট <span class=\"steps__flag steps__flag--soft\">ঐচ্ছিক</span>",
      step2Body: "Non-null কলাম, ইউনিক, চেক, ডিফল্ট এবং ফরেন কি প্রতিটি গেটার হিসেবে প্রকাশ করা হয়।",
      step3Heading: "নামহীন কনস্ট্রাক্টর <span class=\"steps__flag\">প্রয়োজনীয়</span>",
      step3Body: "নিচের <code>fromMap</code> কলব্যাক থেকে এনটিটি তৈরি করতে প্যাকেজটি এটি ব্যবহার করে।",
      step4Heading: "সিরিয়ালাইজেশন <code>toMap</code> <span class=\"steps__flag\">প্রয়োজনীয়</span>",
      step4Body: "কোনো ফিল্ড <code>null</code> হলেও তার <code>ColumnType</code> প্যাকেজকে কলামের টাইপ জানিয়ে দেয়। <code>notNulls</code>-এর ফিল্ডগুলোর জন্য এটি বাদ দেওয়া যায়, কারণ ইনসার্টের সময় সেগুলো কখনো নাল হয় না।",
      step5Heading: "নেমড <code>fromMap</code> কনস্ট্রাক্টর <span class=\"steps__flag\">প্রয়োজনীয়</span>",
      step5Body: "একটি একক SQLite রো থেকে ডি-সিরিয়ালাইজেশন। SQLite-এ বুলিয়ান বা তারিখের কোনো টাইপ নেই: <code>boolean</code> ও <code>dateTime</code> হেল্পার সেগুলোকে আবার রূপান্তর করে।",
      step6Heading: "ইনস্ট্যান্স-সাইড <code>fromMap</code> <span class=\"steps__flag\">প্রয়োজনীয়</span>",
      step6Body: "নেমড কনস্ট্রাক্টরকে র‍্যাপ করে যাতে জেনেরিক গেটারগুলো যেকোনো ইনস্ট্যান্স থেকে এটি কল করতে পারে।",
      crudKicker: "&sect; ০৩ &middot; রানটাইম",
      crudTitle: "CRUD নির্দেশিকা",
