      crudReadTitle: "একটি রো, অনেক রো, একটি কলাম অথবা অনেকগুলো কলাম।",
      crudReadBody: "শর্তটি যায় <code>afterWhere</code>-এ, প্রতিটি মানের জন্য একটি <code>?</code> দিয়ে, আর মানগুলো যায় <code>whereArgs</code>-এ: কোনো মান কখনো SQL-এর ভেতরে জুড়ে দেওয়া হয় না। বুলিয়ান ও তারিখ সেভাবেই রূপান্তরিত হয় যেভাবে b012_data সেগুলো সংরক্ষণ করে।",
