      advKicker: "&sect; 05 &middot; 2.1",
      advTitle: "مزید گہرائی میں",
      advSub: "محفوظ شرائط، غلطیاں، ٹرانزیکشنز، کیز، اسکیمہ کا ارتقا، ویب اور انکرپشن۔ ہر حصہ اپنی جگہ مکمل ہے: صرف وہی پڑھیں جس کی آپ کو ضرورت ہے۔",
      advATitle: "<code>afterWhere</code> کو کبھی صارف کے ان پٹ سے نہ بنائیں۔",
      advA1: "<code>afterWhere</code> جوں کا توں <code>WHERE</code> کے بعد داخل کیا جاتا ہے &mdash; اسی وجہ سے آپ اس میں <code>ORDER BY</code> یا <code>LIMIT</code> شامل کر سکتے ہیں۔ ہر ویلیو کے لیے ایک <code>?</code> رکھیں اور ویلیوز <code>whereArgs</code> میں پاس کریں: اپاسٹروفی والی ویلیو بھی کام کرتی ہے، اور جان بوجھ کر بنائی گئی ویلیو SQL انجیکٹ نہیں کر سکتی۔",
      advA2: "<code>get</code>، <code>getAllSorted</code> اور <code>deleteObjet</code> میں <code>whereArgs</code> ایک پوزیشنل پیرامیٹر ہے جو <code>afterWhere</code> کے بعد آتا ہے، اور باقی جگہوں پر نامزد پیرامیٹر۔ پیکیج خود جو کوئریز بناتا ہے (<code>getLogin</code>، <code>checkIfTableExists</code>، <code>getEntityFileOnDisc</code>، &hellip;) وہ ہمیشہ بانڈ شدہ قدریں استعمال کرتی ہیں۔ جو ٹیبل اور کالم نام SQL کے کلیدی الفاظ ہیں (<code>order</code>، <code>group</code>، &hellip;) انہیں خود بخود واوین میں رکھا جاتا ہے؛ اپنے <code>afterWhere</code> میں انہیں خود واوین میں رکھیں (<code>'\"group\" = ?'</code>)۔",
      advBTitle: "سخت موڈ، یا صرف اطلاع پائیں۔",
      advB1: "ڈیفالٹ طور پر ناکام کال <code>false</code> یا <code>[]</code> واپس کرتی ہے اور غلطی کو <code>debugPrint</code> سے پرنٹ کرتی ہے۔ <code>strict</code> کے ساتھ یہ اس کے بجائے اصل <code>DatabaseException</code> پھینکتی ہے؛ ”کچھ نہیں ملا“ اب بھی <code>null</code> یا <code>[]</code> ہی ہوتا ہے۔ <code>strict</code> کے بغیر، <code>onError</code> کو ہر وہ غلطی ملتی ہے جو <code>false</code> یا <code>[]</code> میں بدل دی گئی ہو۔",
      advCTitle: "سب کچھ یا کچھ بھی نہیں۔",
      advC1: "اندر کال کیا گیا <code>DataAccess</code> کا ہر میتھڈ ٹرانزیکشن کا حصہ بنتا ہے، اور کسی دوسری ٹرانزیکشن کے اندر شروع ہونے والی ٹرانزیکشن اسی میں شامل ہو جاتی ہے۔ ٹرانزیکشن کے اندر ناکام میتھڈ <code>false</code> واپس کرنے کے بجائے غلطی پھینکتا ہے (<code>strict</code> کے بغیر بھی)، تاکہ سب کچھ رول بیک ہو جائے۔",
      advDTitle: "صفحہ بند، ترتیب شدہ، بانڈ شدہ &mdash; یا خام SQL۔",
      advD1: "<code>orderBy</code> بھی <code>afterWhere</code> کی طرح جوں کا توں داخل کیا جاتا ہے: اسے کبھی صارف کے ان پٹ سے نہ بنائیں۔ <code>rawQuery</code>، <code>rawQueryAs</code> اور <code>rawExecute</code> بھی اپنے <code>?</code> پلیس ہولڈرز کو بانڈ کرتے ہیں؛ <code>rawExecute</code> ان قطاروں کی تعداد واپس کرتا ہے جنہیں سٹیٹمنٹ نے بدلا۔",
      advETitle: "ری پلیس، مرکب کیز، انڈیکسز، فارن کیز۔",
      advE1: "<code>orReplace</code> کے ساتھ، اگر اسی کی والی قطار پہلے سے موجود ہو تو اسے بدل دیا جاتا ہے۔ اینٹٹی کے تین اختیاری گیٹرز کئی کالموں پر مشتمل پرائمری کی (<code>pKeyAuto</code> کی جگہ)، انڈیکسز اور منفرد انڈیکسز بیان کرتے ہیں؛ غائب انڈیکسز بنا دیے جاتے ہیں، موجودہ ٹیبل پر بھی:",
      advE2: "<code>fKeys</code> میں بیان کی گئی فارن کیز صرف اسی وقت نافذ ہوتی ہیں جب پہلی رسائی سے پہلے <code>enforceForeignKeys</code> سیٹ کیا جائے (<code>PRAGMA foreign_keys = ON</code>)۔ یہ ڈیفالٹ طور پر بند ہے، کیونکہ انہیں نافذ کرنے سے وہ ایپلیکیشن ٹوٹ سکتی ہے جو پیرنٹ سے پہلے چائلڈ انسرٹ کرتی ہے۔",
      advFTitle: "مستحکم ٹیبل نام، نئے کالمز، مائیگریشنز۔",
      advF1: "ٹیبل کا نام اس کی کلاس کے نام پر ہوتا ہے۔ اوبفسکیٹ شدہ بلڈز (اور ویب ریلیز بلڈز) کلاسوں کے نام بدل دیتے ہیں، اس لیے ان اینٹٹیز کو رجسٹر کریں جن کا ٹیبل نام نہیں بدلنا چاہیے؛ ہر میتھڈ رجسٹریشن کی پیروی کرتا ہے، ان میتھڈز سمیت جنہیں صرف ٹائپ ملتی ہے۔ <strong>براؤزر میں رجسٹریشن لازمی ہے۔</strong>",
      advF2: "<code>autoAddColumns</code> کے ساتھ (ڈیفالٹ طور پر بند)، اینٹٹی میں شامل کی گئی فیلڈ اس کے ٹیبل کا نیا کالم بن جاتی ہے؛ کالمز کبھی حذف نہیں کیے جاتے اور نہ ان کا نام بدلا جاتا ہے۔ ہر مائیگریشن ڈیٹابیس کھلنے پر ترتیب سے ایک بار چلتی ہے، اپنی الگ ٹرانزیکشن میں جو <code>PRAGMA user_version</code> سیٹ کرتی ہے؛ ناکام مرحلہ رول بیک ہو جاتا ہے اور ڈیٹابیس کھلنے میں ناکامی کا سبب بنتا ہے۔ دونوں کو پہلی رسائی سے پہلے سیٹ کریں۔",
      advGTitle: "ہر ایپلیکیشن کا ایک فولڈر، فائلیں محفوظ طریقے سے لکھی جاتی ہیں۔",
      advG1: "<strong>Android، iOS، macOS</strong>: پلیٹ فارم کا ڈیٹابیسز فولڈر، جیسا کہ 2.0.3 میں۔",
      advG2: "<strong>Windows، Linux</strong>: ڈیٹابیسز، <code>dbName</code> اور فائلیں ایپلیکیشن سپورٹ فولڈر میں جاتی ہیں۔ 2.0.3 نے موجودہ ڈائرکٹری کے تحت جو ڈیٹابیس بنایا تھا (<code>.dart_tool/sqflite_common_ffi/databases</code>) وہ مل جاتا ہے اور اپنی جگہ پر ہی رہتا ہے، اس لیے کچھ غائب نہیں ہوتا۔",
      advG3: "<code>changeDB</code> اپنی ضرورت کا فولڈر خود بنا لیتا ہے۔",
