      advG5: "فائل کا <em>نام</em> <code>filesPath</code> سے باہر اشارہ نہیں کر سکتا (<code>'../x'</code> ایک <code>ArgumentError</code> پھینکتا ہے)؛ واضح مطلق پاتھز پہلے کی طرح کام کرتے ہیں۔",
      advHTitle: "وہی API، براؤزر میں۔",
      advH1: "SQLite بطور WebAssembly چلتا ہے (ڈیفالٹ طور پر <code>sqlite3mc.wasm</code>؛ کوئی اور ماڈیول استعمال کرنے کے لیے <code>DataAccess.instance.webSqliteWasmUri</code> سیٹ کریں)۔ ڈیٹابیسز اور <code>DiscData</code> کی فائلیں IndexedDB میں رہتی ہیں؛ مستقل اسٹوریج کی درخواست کی جاتی ہے۔",
      advH2: "ہر رائٹ آپریشن اپنے future کے مکمل ہونے سے پہلے IndexedDB میں محفوظ ہو جاتا ہے۔",
      advH3: "ایک وقت میں ایک ٹیب: اسی ڈیٹابیس کو کھولنے والے دوسرے ٹیب کو ایسی کاپی کے بجائے جو پہلے ٹیب کو اوور رائٹ کر دیتی، ایک واضح <code>StateError</code> ملتا ہے۔ اس کے لیے Web Locks API درکار ہے، جو <code>https</code> اور <code>localhost</code> پر دستیاب ہے۔",
      advH4: "اینٹٹیز کا <a href=\"#v21-names\">رجسٹر</a> ہونا ضروری ہے۔",
      advH5: "<code>DataAccess.db</code> اور <code>openDB</code> (sqflite آبجیکٹس) دستیاب نہیں؛ <code>DiscData.getFile</code> <code>null</code> واپس کرتا ہے (کوئی فائل سسٹم نہیں ہے)۔",
      advH6: "صارف کے صاف کرنے پر براؤزر اب بھی سائٹ کا ڈیٹا مٹا سکتا ہے۔",
      advITitle: "گم شدہ یا چوری شدہ ڈیوائس کے خلاف۔",
      advI1: "ڈیٹابیس اور نام سے محفوظ کی گئی فائلیں <a class=\"ext-link\" href=\"https://github.com/utelle/SQLite3MultipleCiphers\" target=\"_blank\" rel=\"noopener\">SQLite3MultipleCiphers</a> (MIT لائسنس) سے انکرپٹ کی جا سکتی ہیں۔ یہ انجن <strong>اپنی ایپلیکیشن کی</strong> <code>pubspec.yaml</code> میں منتخب کریں (براؤزر میں <code>setup_web</code> پہلے ہی <code>sqlite3mc.wasm</code> فراہم کرتا ہے):",
      advI2: "نیا ڈیٹابیس انکرپٹ شدہ بنایا جاتا ہے؛ غلط کلید <code>StateError</code> پھینکتی ہے۔",
      advI3: "پہلے انجن کی جانچ کی جاتی ہے: اگر وہ انکرپٹ نہیں کرتا، تو ایک <code>StateError</code> بتاتا ہے کہ <code>pubspec.yaml</code> میں کیا شامل کرنا ہے۔ غلطی سے کبھی کوئی ڈیٹابیس غیر انکرپٹ شدہ نہیں بنتا۔",
      advI4: "کسی موجودہ غیر انکرپٹ شدہ ڈیٹابیس کے لیے دی گئی کلید مسترد کر دی جاتی ہے (<code>encryptDatabase</code> استعمال کریں)؛ انکرپٹ شدہ ڈیٹابیس اپنی کلید کے بغیر کبھی نہیں کھلتا۔",
      advI5: "<code>DiscData</code> کے ذریعے نام سے محفوظ کی گئی فائلیں ایک رینڈم کلید سے انکرپٹ (AES-256-GCM) کی جاتی ہیں جو انکرپٹ شدہ ڈیٹابیس کے اندر رکھی جاتی ہے، اس لیے ڈیٹابیس کی کلید بدلنے سے کوئی فائل دوبارہ نہیں لکھی جاتی۔ کسی واضح پاتھ پر لکھی گئی فائلیں غیر انکرپٹ شدہ رہتی ہیں، جب تک <code>saveDataToDisc(..., encrypt: true)</code> استعمال نہ کیا جائے۔",
      advI6: "<code>encryptDatabase</code> ان فائلوں کو بھی انکرپٹ کرتا ہے جو <code>DiscData</code> نے نام سے محفوظ کیں، اور ان کو بھی جن کے نام آپ <code>alsoFiles</code> میں دیتے ہیں؛ فائلوں کے فولڈر میں کسی اور چیز کو ہاتھ نہیں لگایا جاتا۔",
      advI7: "Android اور iOS پر، انکرپٹ شدہ ڈیٹابیس سسٹم کے SQLite کے بجائے <code>package:sqlite3</code> کے ساتھ آنے والے انجن سے گزرتا ہے۔",
      advI8: "<strong>b012_data کلید کبھی محفوظ نہیں کرتا</strong>: آپ کی ایپلیکیشن ہر آغاز پر اسے فراہم کرتی ہے۔ ڈیوائس پر ایک رینڈم کلید سسٹم والٹ (Keystore، Keychain، Windows ڈیٹا پروٹیکشن) میں رکھیں؛ براؤزر میں کوئی والٹ نہیں ہوتا، اس لیے کلید کسی ایسی چیز سے آنی چاہیے جو صارف ٹائپ کرے۔",
      notesKicker: "&sect; 06 &middot; خاص صورتیں",
      notesTitle: "جاننے کی باتیں",
      notesSub: "دو باریکیاں جو بعد میں ڈیبگنگ کا وقت بچاتی ہیں۔",
      note1Title: "ٹیبل نہ ہونے کی استثنا",
